package roar

import (
	"fmt"
	"sync"
	"testing"

	"github.com/evanoberholster/imageIdx/internal/bench"
)

// Deterministic operation matrix for the exported Bitmap API. Every dataset
// is generated by the shared bench harness from a stable seed derived only
// from N and Density, every sub-benchmark name is built from stable labels,
// and every result is consumed through a package-level sink so the compiler
// cannot eliminate the measured work:
//
//	go test ./roar/ -run='^$' -bench='BenchmarkBitmap' -benchmem -count=10
//
// Sub-benchmarks are named BenchmarkBitmap/<Op>/N=<n>/Density=<tier> with
// multi-way cases adding K=<k>/Order=<order>.

// matrixSink consumes benchmark results so the compiler cannot eliminate the
// measured work. It is assigned only deterministic result values.
var matrixSink uint64

// matrixMissOffset moves a member ID into a container key region no generated
// dataset reaches, so miss probes are guaranteed absent.
const matrixMissOffset = uint64(1) << 46

// matrixPair is the dataset shared by every operation at one (N, Density)
// point. sets holds eight full-cardinality operands; small is the N/10
// operand that varies AndMany ordering.
type matrixPair struct {
	n       int
	density bench.Density
	sets    [8]Bitmap
	small   Bitmap
	hits    []uint64
	misses  []uint64
}

type matrixBoundaryCase struct {
	label       string
	left, right Bitmap
}

func matrixSeed(n int, d bench.Density) int64 {
	return int64(n)*1_000_003 + int64(d)*104_729 + 17
}

func matrixSizeLabel(n int, d bench.Density) string {
	return fmt.Sprintf("N=%d/Density=%s", n, d)
}

func matrixMustBitmap(ids []uint64) Bitmap {
	bitmap, err := FromSorted(ids)
	if err != nil {
		panic(fmt.Sprintf("matrix benchmark: FromSorted: %v", err))
	}
	return bitmap
}

// matrixIncrementIDs returns ids shifted by delta, preserving ascending order.
func matrixIncrementIDs(ids []uint64, delta uint64) []uint64 {
	out := make([]uint64, len(ids))
	for index, id := range ids {
		out[index] = id + delta
	}
	return out
}

var (
	matrixOnce  sync.Once
	matrixPairs []matrixPair
)

// benchmarkPairs lazily builds the shared matrix once per process. The 10M
// tier remains opt-in through the harness.
func benchmarkPairs(b *testing.B) []matrixPair {
	matrixOnce.Do(func() {
		sizes := bench.Sizes(b)
		densities := bench.Densities()
		matrixPairs = make([]matrixPair, 0, len(sizes)*len(densities))
		for _, n := range sizes {
			for _, d := range densities {
				matrixPairs = append(matrixPairs, newMatrixPair(n, d))
			}
		}
	})
	return matrixPairs
}

func newMatrixPair(n int, d bench.Density) matrixPair {
	seed := matrixSeed(n, d)
	pair := matrixPair{n: n, density: d}
	ids := bench.BitmapIDs(seed, n, d)
	pair.sets[0] = matrixMustBitmap(ids)
	for k := 1; k < len(pair.sets); k++ {
		pair.sets[k] = matrixMustBitmap(bench.BitmapIDs(seed+int64(k)*7919, n, d))
	}
	small := n / 10
	if small < 1 {
		small = 1
	}
	pair.small = matrixMustBitmap(bench.BitmapIDs(seed+65_537, small, d))
	for index := 0; index < len(ids); index += 64 {
		pair.hits = append(pair.hits, ids[index])
		pair.misses = append(pair.misses, ids[index]+matrixMissOffset)
	}
	return pair
}

// andManyArgs places the smaller operand at the requested position.
func (p *matrixPair) andManyArgs(k int, order string) []Bitmap {
	args := make([]Bitmap, k)
	copy(args, p.sets[:k])
	index := 0
	switch order {
	case "SmallestMiddle":
		index = k / 2
	case "SmallestLast":
		index = k - 1
	}
	args[index] = p.small
	return args
}

// BenchmarkBitmap is the exported-API matrix: pair operations, cardinality
// only operations, membership, materialization, iteration, and N-way
// intersection with small-operand ordering, plus the Boundary group.
func BenchmarkBitmap(b *testing.B) {
	runPair := func(op string, fn func(p *matrixPair) uint64) {
		b.Run(op, func(b *testing.B) {
			pairs := benchmarkPairs(b)
			for index := range pairs {
				pair := &pairs[index]
				b.Run(matrixSizeLabel(pair.n, pair.density), func(b *testing.B) {
					b.ReportAllocs()
					b.ResetTimer()
					for b.Loop() {
						matrixSink = fn(pair)
					}
				})
			}
		})
	}

	runPair("And2", func(p *matrixPair) uint64 { return And(p.sets[0], p.sets[1]).Cardinality() })
	runPair("Or2", func(p *matrixPair) uint64 { return Or(p.sets[0], p.sets[1]).Cardinality() })
	runPair("AndNot2", func(p *matrixPair) uint64 { return AndNot(p.sets[0], p.sets[1]).Cardinality() })
	runPair("AndCardinality2", func(p *matrixPair) uint64 { return AndCardinality(p.sets[0], p.sets[1]) })
	runPair("OrCardinality2", func(p *matrixPair) uint64 { return OrCardinality(p.sets[0], p.sets[1]) })
	runPair("AndNotCardinality2", func(p *matrixPair) uint64 { return AndNotCardinality(p.sets[0], p.sets[1]) })
	runPair("Intersects2", func(p *matrixPair) uint64 {
		if Intersects(p.sets[0], p.sets[1]) {
			return 1
		}
		return 0
	})

	b.Run("Contains", func(b *testing.B) {
		pairs := benchmarkPairs(b)
		for index := range pairs {
			pair := &pairs[index]
			bitmap := pair.sets[0]
			label := matrixSizeLabel(pair.n, pair.density)
			hits, misses := pair.hits, pair.misses
			b.Run(label+"/Result=Hit", func(b *testing.B) {
				b.ReportAllocs()
				b.ResetTimer()
				for b.Loop() {
					count := uint64(0)
					for _, id := range hits {
						if bitmap.Contains(id) {
							count++
						}
					}
					matrixSink = count
				}
			})
			b.Run(label+"/Result=Miss", func(b *testing.B) {
				b.ReportAllocs()
				b.ResetTimer()
				for b.Loop() {
					count := uint64(0)
					for _, id := range misses {
						if bitmap.Contains(id) {
							count++
						}
					}
					matrixSink = count
				}
			})
		}
	})

	b.Run("AppendTo", func(b *testing.B) {
		pairs := benchmarkPairs(b)
		for index := range pairs {
			pair := &pairs[index]
			bitmap := pair.sets[0]
			buffer := make([]uint64, 0, bitmap.Cardinality())
			b.Run(matrixSizeLabel(pair.n, pair.density), func(b *testing.B) {
				b.ReportAllocs()
				b.ResetTimer()
				for b.Loop() {
					buffer = bitmap.AppendTo(buffer[:0])
					matrixSink = uint64(len(buffer)) ^ buffer[0] ^ buffer[len(buffer)-1]
				}
			})
		}
	})

	b.Run("Iterator", func(b *testing.B) {
		pairs := benchmarkPairs(b)
		for index := range pairs {
			pair := &pairs[index]
			bitmap := pair.sets[0]
			b.Run(matrixSizeLabel(pair.n, pair.density), func(b *testing.B) {
				b.ReportAllocs()
				b.ResetTimer()
				for b.Loop() {
					sum := uint64(0)
					for iterator := bitmap.Iterator(); iterator.Next(); {
						sum += iterator.Value()
					}
					matrixSink = sum
				}
			})
		}
	})

	b.Run("AndMany", func(b *testing.B) {
		pairs := benchmarkPairs(b)
		orders := []string{"SmallestFirst", "SmallestMiddle", "SmallestLast"}
		for _, k := range []int{4, 8} {
			for index := range pairs {
				pair := &pairs[index]
				for _, order := range orders {
					args := pair.andManyArgs(k, order)
					label := fmt.Sprintf("K=%d/N=%d/Density=%s/Order=%s", k, pair.n, pair.density, order)
					b.Run(label, func(b *testing.B) {
						b.ReportAllocs()
						b.ResetTimer()
						for b.Loop() {
							matrixSink = AndMany(args...).Cardinality()
						}
					})
				}
			}
		}
	})

	b.Run("Boundary", func(b *testing.B) {
		empty := Bitmap{}
		singleA := matrixMustBitmap(bench.BitmapIDs(1, 1, bench.Sparse))
		singleB := matrixMustBitmap(bench.BitmapIDs(2, 1, bench.Sparse))
		cases := []matrixBoundaryCase{
			{label: "Empty", left: empty, right: singleA},
			{label: "SingleID", left: singleA, right: singleB},
			{label: "Identical", left: singleA, right: singleA},
		}
		for _, size := range []int{65535, 65536, 65537} {
			left := matrixMustBitmap(bench.DenseIDs(size))
			right := matrixMustBitmap(matrixIncrementIDs(bench.DenseIDs(size), 1))
			cases = append(cases, matrixBoundaryCase{
				label: fmt.Sprintf("N=%d", size),
				left:  left,
				right: right,
			})
		}

		b.Run("And", func(b *testing.B) {
			for _, boundary := range cases {
				b.Run(boundary.label, func(b *testing.B) {
					b.ReportAllocs()
					b.ResetTimer()
					for b.Loop() {
						matrixSink = And(boundary.left, boundary.right).Cardinality()
					}
				})
			}
		})
		b.Run("Or", func(b *testing.B) {
			for _, boundary := range cases {
				b.Run(boundary.label, func(b *testing.B) {
					b.ReportAllocs()
					b.ResetTimer()
					for b.Loop() {
						matrixSink = Or(boundary.left, boundary.right).Cardinality()
					}
				})
			}
		})
		b.Run("AndNot", func(b *testing.B) {
			for _, boundary := range cases {
				b.Run(boundary.label, func(b *testing.B) {
					b.ReportAllocs()
					b.ResetTimer()
					for b.Loop() {
						matrixSink = AndNot(boundary.left, boundary.right).Cardinality()
					}
				})
			}
		})
		b.Run("Intersects", func(b *testing.B) {
			for _, boundary := range cases {
				b.Run(boundary.label, func(b *testing.B) {
					b.ReportAllocs()
					b.ResetTimer()
					for b.Loop() {
						if Intersects(boundary.left, boundary.right) {
							matrixSink = 1
						} else {
							matrixSink = 0
						}
					}
				})
			}
		})
		b.Run("Contains", func(b *testing.B) {
			ids := singleA.AppendTo(nil)
			hit := ids[0]
			miss := hit + matrixMissOffset
			b.Run("Hit", func(b *testing.B) {
				b.ReportAllocs()
				b.ResetTimer()
				for b.Loop() {
					if singleA.Contains(hit) {
						matrixSink = 1
					} else {
						matrixSink = 0
					}
				}
			})
			b.Run("Miss", func(b *testing.B) {
				b.ReportAllocs()
				b.ResetTimer()
				for b.Loop() {
					if singleA.Contains(miss) {
						matrixSink = 1
					} else {
						matrixSink = 0
					}
				}
			})
		})
		b.Run("AndMany/Identical", func(b *testing.B) {
			identical := cases[len(cases)-1].left
			b.ReportAllocs()
			b.ResetTimer()
			for b.Loop() {
				matrixSink = AndMany(identical, identical, identical, identical).Cardinality()
			}
		})
	})
}
